{v:'VER',what:'the what is new card is stamped within 0.15 of the build, leads with the COMBAT FEEL news shown whole, and no longer carries the retired belt lines',
 run:function(){
   if(typeof WHATSNEW==='undefined'||typeof WHATSNEW_VER==='undefined'||typeof VER==='undefined'||typeof wnShort!=='function') return 'SKIP: this build has no what is new card';
   if(parseFloat(WHATSNEW_VER)>26.61+0.001) return 'SKIP: the card has moved on, a later card check covers it';
   var bad=[], d=parseFloat(VER)-parseFloat(WHATSNEW_VER), i, t;
   if(!(d<=0.15+1e-9)) bad.push('the card is stamped v'+WHATSNEW_VER+', '+d.toFixed(2)+' behind v'+VER);
   if(String(WHATSNEW[1]).indexOf('COMBAT'+' FEEL.')!==0) bad.push('the card does not lead with the combat feel news');
   else if(wnShort(WHATSNEW[1]).slice(-3)==='...') bad.push('the new line is cut on the card');
   if(String(WHATSNEW[0]).indexOf('THIS IS AN'+' ALPHA')!==0) bad.push('the card no longer opens with the alpha line');
   for(i=0;i<WHATSNEW.length;i++){ t=String(WHATSNEW[i]); if(t.indexOf('BELT'+' KEYS.')===0||t.indexOf('NEW'+' BELT.')===0) bad.push('a retired belt line is still on the card: '+t.slice(0,12)); }
   return bad.length?bad.join('; '):null; }},
